<?php

# @autogenerated
declare(strict_types=1);

use Civi\Lughauth\Features\Document\TemplateAsset\Domain\ValueObject\Accessor\TemplateAssetTypeAccessor;
use PHPUnit\Framework\TestCase;

/**
 * Unit tests for the TemplateAssetTypeAccessor trait.
 *
 * Covers null default, string/VO assignment via withType,
 * getType/type accessors, and isTypeChanged with/without original.
 */
class TemplateAssetTypeAccessorUnitTest extends TestCase
{
    /**
     * Asserts that withType creates a new instance with the Type set
     * from a string value, and getType returns the primitive string.
     */
    public function testWithTypeFromString(): void
    {
        // Arrange
        $holder = new ImplWithTemplateAssetTypeAccessorUnitTest();

        // Act
        $result = $holder->withType('one');

        // Assert
        $this->assertNotSame($holder, $result);
        $this->assertEquals('one', $result->getType());
    }
    /**
     * Asserts that withtype has access to the value object
     * from a string value, and getType returns the primitive string.
     */
    public function testWithTypeFromValueObject(): void
    {
        // Arrange
        $holder = new ImplWithTemplateAssetTypeAccessorUnitTest();

        // Act
        $result = $holder->withType('one');

        // Assert
        $this->assertNotSame($holder, $result);
        $this->assertEquals('one', $result->type()->value());
    }
    public function testChangedType(): void
    {
        // Arrange
        $holder = new ImplWithTemplateAssetTypeAccessorUnitTest()->withType('one');
        $original = $holder->withType('one');
        $same = $holder->withType('one');
        $modified = $holder->withType('other');

        // Act
        $withSame = $original->isTypeChanged($same);
        $withDiferent = $original->isTypeChanged($modified);

        // Assert
        $this->assertFalse($withSame);
        $this->assertTrue($withDiferent);
    }
}
class ImplWithTemplateAssetTypeAccessorUnitTest
{
    use TemplateAssetTypeAccessor;
}
